/**
 * Python `bytes` helpers: UTF-8 encoding and `repr(bytes)`.
 *
 * `encode_canonical_json` hands back a bytes object, and the script prints it,
 * so the exact `b'...'` rendering matters.
 */

/** `str.encode("utf-8")`. */
export function encodeUtf8(text) {
  return new TextEncoder().encode(text);
}

const ESCAPES = new Map([
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
  [0x5c, '\\\\'],
]);

/**
 * `repr(b)` for a bytes object.
 *
 * Single quotes are used unless the payload contains a single quote but no
 * double quote, in which case Python switches the outer quotes. Backslash,
 * tab, newline and carriage return get their short escapes; every other byte
 * outside the printable ASCII range is written as `\xhh`.
 */
export function bytesRepr(bytes) {
  const hasSingle = bytes.includes(0x27);
  const hasDouble = bytes.includes(0x22);
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteByte = quote.charCodeAt(0);

  let body = '';
  for (const byte of bytes) {
    const escape = ESCAPES.get(byte);
    if (escape !== undefined) {
      body += escape;
    } else if (byte === quoteByte) {
      body += `\\${quote}`;
    } else if (byte < 0x20 || byte >= 0x7f) {
      body += `\\x${byte.toString(16).padStart(2, '0')}`;
    } else {
      body += String.fromCharCode(byte);
    }
  }

  return `b${quote}${body}${quote}`;
}

