#!/usr/bin/env node
/* Focused sweep of repr(float) formatting: exponent boundaries + bit patterns. */
import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test3_executable';
const inputs = [];

// Exponent boundaries: repr switches to scientific notation at both ends.
for (let k = -330; k <= 309; k += 1) {
  inputs.push(`1e${k}`);
  if (k >= -12 && k <= 20) inputs.push(`1.2345678901234567e${k}`, `9.87e${k}`);
}

// Random doubles from raw bit patterns, plus tiny/huge magnitudes.
const bits = new DataView(new ArrayBuffer(8));
let seed = 987654321;
const rnd = () => {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed / 0x7fffffff;
};
for (let i = 0; i < 300; i++) {
  bits.setUint32(0, Math.floor(rnd() * 0xffffffff));
  bits.setUint32(4, Math.floor(rnd() * 0xffffffff));
  const value = bits.getFloat64(0);
  inputs.push(Number.isFinite(value) ? value.toString() : `${rnd()}`);
}
// Subnormals and the smallest steps above/below powers of two.
for (let i = 1; i <= 30; i++) inputs.push((i * 5e-324).toString(), (2 ** -i * 1.0000000000000002).toString());

let failures = 0;
for (const value of inputs) {
  const a = spawnSync('node', ['/output/test3.mjs', '--a', value], { encoding: 'utf8' });
  const b = spawnSync(EXE, ['--a', value], { encoding: 'utf8' });
  if (a.stdout !== b.stdout || a.status !== b.status) {
    failures += 1;
    console.log('MISMATCH %j -> node=%j exe=%j', value, a.stdout, b.stdout);
  }
}
console.log(`\n${inputs.length - failures}/${inputs.length} matched`);
process.exit(failures ? 1 : 0);

