toolUseResult.originalFile:
/**
 * Public surface of the `canonicaljson` package, as far as this program uses
 * it: a canonical encoder that returns UTF-8 bytes.
 *
 * Canonical form means shortest possible whitespace, keys sorted by code
 * point, non-ASCII characters left unescaped, and NaN/Infinity rejected.
 */

import { encodeToString } from './jsonencoder.mjs';
import { encodeUtf8 } from './pybytes.mjs';
import { PyTypeError } from './errors.mjs';

/** `default=` hook: unwrap frozen mappings, refuse anything else. */
function fallback(value) {
  if (value instanceof Map) return value;
  throw new PyTypeError(`Object of type ${value?.constructor?.name} is not JSON serializable`);
}

/**
 * `canonicaljson.encode_canonical_json(obj) -> bytes`.
 *
 * @returns {Uint8Array} UTF-8 encoded canonical JSON
 */
export function encodeCanonicalJson(value) {
  return encodeUtf8(encodeToString(value, fallback));
}

/**
 * `canonicaljson.encode_pretty_printed_json(obj) -> bytes`, kept alongside the
 * canonical encoder for completeness. Indented output is not canonical, so it
 * shares only the scalar rules.
 */
export function encodePrettyPrintedJson(value) {
  return encodeUtf8(encodeToString(value, fallback));
}

